以下是一个Python脚本的示例，使用 WHOIS、BGP 和 IP 地理位置数据来绘制目标组织的网络拓扑图。请注意，这只是一个简化的示例，实际应用中可能需要更复杂的处理和错误处理。

```python
import requests
import json
import socket
from ip2geotools.databases.nonfree import DbIpCity

def get_whois(domain):
    url = f"https://api.who.is/whois/{domain}"
    response = requests.get(url)
    if response.status_code == 200:
        return response.json()
    else:
        print(f"Error: Unable to retrieve WHOIS data for {domain}")
        return None

def get_bgp_data(ip):
    url = f"https://bgp.he.net/ip/{ip}"
    response = requests.get(url)
    if response.status_code == 200:
        return json.loads(response.text)['data']
    else:
        print(f"Error: Unable to retrieve BGP data for {ip}")
        return None

def get_ip_geolocation(ip):
    try:
        city = DbIpCity.get(ip, api_key='free')
        return (city.country_code, city.city.name)
    except socket.gaierror:
        print(f"Error: Unable to retrieve geolocation data for {ip}")
        return None

def main(target_domain):
    whois_data = get_whois(target_domain)
    if whois_data is None:
        return

    ip_addresses = set()
    ip_addresses.add(socket.gethostbyname(target_domain))

    for record in whois_data['records']:
        if 'ipAddress' in record:
            ip_addresses.add(record['ipAddress'])

    bgp_data = {}
    for ip in ip_addresses:
        data = get_bgp_data(ip)
        if data is not None:
            bgp_data[ip] = data

    geolocation_data = {}
    for ip, data in bgp_data.items():
        country_code, city = get_ip_geolocation(ip)
        if country_code is not None:
            geolocation_data[ip] = (country_code, city)

    print("Network Topology:")
    for ip, data in bgp_data.items():
        country_code, city = geolocation_data.get(ip, ("Unknown", "Unknown"))
        print(f"{ip}: {data['prefix']}/{data['length']} ({data['AS']}) - {country_code}: {city}")

if __name__ == "__main__":
    target_domain = input("Enter the target domain: ")
    main(target_domain)
```

此脚本首先使用 WHOIS API 获取目标域名的信息。然后，它获取与该域名关联的 IP 地址（如果有多个）。对于每个 IP 地址，它使用 BGP.HE.NET API 获取路由数据和 IP地理位置数据。

