To create a decentralized command and control (C2) framework using blockchain smart contracts, we'll follow these steps:

1. Choose a suitable blockchain platform: Ethereum is a popular choice due to its support for smart contracts and the large ecosystem of tools and libraries available.

2. Design the smart contract architecture:
   - C2Command: Stores C2 instructions and manages their lifecycle.
   - C2Client: Allows client nodes to fetch new commands, mark them as completed, and submit feedback.
   - C2Server: Manages server nodes and their tasks.
   - C2Admin: Handles permissions and access control for administrators.

3. Implement the smart contracts:

**C2Command.sol**

```solidity
pragma solidity ^0.8.0;

import "@openzeppelin/contracts/access/Ownable.sol";

contract C2Command is Ownable {
    struct Command {
        bytes data;
        bool completed;
        address sender;
    }

    mapping(uint => Command) public commands;
    uint currentId = 1;

    event CommandCreated(uint id);
    event CommandCompleted(uint id);

    function createCommand(bytes memory _data) public onlyOwner returns (uint) {
        commands[currentId] = Command(_data, false, msg.sender);
        emit CommandCreated(currentId);
        return currentId++;
    }

    function markAsCompleted(uint _id) public {
        Command memory command = commands[_id];
        require(msg.sender == command.sender || msg.sender == owner(), "Not authorized");
        require(!command.completed, "Already completed");
        command.completed = true;
        emit CommandCompleted(_id);
    }
}
```

**C2Client.sol**

```solidity
pragma solidity ^0.8.0;

import "@openzeppelin/contracts/access/Ownable.sol";
import "./C2Command.sol";

contract C2Client is Ownable {
    using SafeMath for uint256;

    C2Command public commandContract;
    uint pendingCommandId;

    event CommandFetched(uint id);
    event CommandSubmitted(uint id, bool success);

    constructor(address _commandContract) {
        commandContract = C2Command(_commandContract);
    }

    function fetchNewCommand() public {
        pendingCommandId = commandContract.createCommand(0x0); // Placeholder data
        emit CommandFetched(pendingCommandId);
    }

    function submitFeedback(bool _success) public {
        require(pendingCommandId > 0, "No pending command");
        commandContract.markAsCompleted(pendingCommandId);
        pendingCommandId = 0;
        emit CommandSubmitted(pendingCommandId, _success);
    }
}
```

**C2Server.sol**

```solidity
pragma solidity ^0.8.0;

import "@openzeppelin/contracts/access/Ownable.sol";
import "./C2Client.sol";

contract C2Server is Ownable {
    mapping(address => C2Client) public clients;
    address[] public activeClients;

    event ClientAdded(address client);
    event TaskAssigned(uint taskId, address client);

    function addClient(C2Client _client) public onlyOwner {
        require(clients[_client] == address(0), "Already registered");
        clients[_client] = _client;
        activeClients.push(_client);
        emit ClientAdded(_client);
    }

    function assignTask(uint _taskId, address _client) public onlyOwner {
        C2Client memory client = clients[_client];
        require(client != address(0), "Invalid client");
        client.fetchNewCommand();
        emit TaskAssigned(_taskId, _client);
    }
}
```

**C2Admin.sol**

```solidity
pragma solidity ^0.8.0;

import "@openzeppelin/contracts/access/Ownable.sol";
import "./C2Server.sol";

contract C2Admin is Ownable {
    C2Server public serverContract;

    constructor(address _server) {
        serverContract = C2Server(_server);
    }

    function registerClient(C2Client _client) public onlyOwner {
        serverContract.addClient(_client);
    }
}
```

4. Deploy the smart contracts on the chosen blockchain platform.

5. Interact with the deployed contracts using web3.js, web3.py, or other preferred libraries to create commands, assign tasks, fetch commands, and submit feedback.

