1. 定义LNK文件头部结构：
```c
typedef struct _SHELL_LINK_HEADER {
    DWORD   clSize;
    DWORD   dwSignature;
    WORD    wLinkFlags;
    WORD    wInfoFlags;
    DWORD   nFileAttributes;
    FILETIME ftCreationTime;
    FILETIME ftAccessTime;
    FILETIME ftWriteTime;
    FILETIME ftExpansionTime;
} SHELL_LINK_HEADER, *PSHELL_LINK_HEADER;
```
1. 定义LNK文件结构：
```c
typedef struct _SHELL_LINK {
    SHELL_LINK_HEADER header;
    DWORD     nIDString;
    WORD      wVersion;
    WORD      wImpFlags;
    DWORD     dwFileAttributes;
    FILETIME  ftCreationTime;
    FILETIME  ftAccessTime;
    FILETIME  ftWriteTime;
    FILETIME  ftExpansionTime;
    DWORD     nFileSizeHigh;
    DWORD     nFileSizeLow;
    DWORD     dwFileAttributes2;
    FILETIME  ftLocalCreationTime;
    FILETIME  ftLocalLastWriteTime;
    WORD      wModifier1;
    WORD      wModifier2;
    DWORD     dwSeed;
    BYTE     bHasExpansion;
    BYTE     bReserved1[9];
    WCHAR    szFileAttributes[1];
} SHELL_LINK, *PSHELL_LINK;
```
1. 定义LNK文件头部签名和标志位：
```c
#define LNK_SIGNATURE         0xFFFFFFFF
#define LNK_FLAG_HAS_LINK_INFO 0x0002
#define LNK_FLAG_HAS_RELATIVE_PATH   0x0010
```
1. 定义生成LNK文件函数：
```c
BOOL CreateLnkFile(LPCWSTR lpTargetPath, LPCWSTR lpLinkPath)
{
    HANDLE hFile;
    PSHELL_LINK pShellLink;

    // 创建目标文件句柄
    hFile = CreateFile(lpTargetPath, GENERIC_WRITE, FILE_SHARE_READ | FILE_SHARE_WRITE, NULL, CREATE_ALWAYS, FILE_ATTRIBUTE_NORMAL, NULL);
    if (hFile == INVALID_HANDLE_VALUE)
        return FALSE;

    // 创建LNK文件头部结构
    SHELL_LINK_HEADER header = {sizeof(SHELL_LINK), LNK_SIGNATURE, LNK_FLAG_HAS_LINK_INFO | LNK_FLAG_HAS_RELATIVE_PATH, 0};
    DWORD dwSize = sizeof(SHELL_LINK) - sizeof(WCHAR);
    pShellLink = (PSHELL_LINK)malloc(dwSize);

    // 填充LNK文件结构
    memcpy(pShellLink, &header, sizeof(SHELL_LINK_HEADER));
    pShellLink->nIDString = 0;
    pShellLink->wVersion = 1;
    pShellLink->wImpFlags = 0x200;
    pShellLink->dwFileAttributes = FILE_ATTRIBUTE_NORMAL;

    // 创建LNK文件
    if (!WriteFile(hFile, pShellLink, dwSize, NULL, NULL))
    {
        free(pShellLink);
        CloseHandle(hFile);
        return FALSE;
    }

    free(pShellLink);
    CloseHandle(hFile);

    return TRUE;
}
```
