3. 编写清除卷影副本的函数：
```csharp
private void DeleteShadowCopies(string volumePath)
{
    // 获取系统还原工具的路径
    string systemRestoreTool = Path.Combine(Environment.SystemDirectory, "Sysnative", "sr.exe");

    if (!File.Exists(systemRestoreTool))
    {
        Console.WriteLine("系统还原工具不存在。");
        return;
    }

    // 启动命令行进程以删除卷影副本
    ProcessStartInfo startInfo = new ProcessStartInfo
    {
        FileName = systemRestoreTool,
        Arguments = $"/delete /v:{volumePath} /p:1",
        RedirectStandardError = true,
        UseShellExecute = false,
        CreateNoWindow = true
    };

    Process process = new Process { StartInfo = startInfo };
    process.Start();

    string errorOutput = process.StandardError.ReadToEnd();
    if (!string.IsNullOrEmpty(errorOutput))
    {
        Console.WriteLine("删除卷影副本时出错：");
        Console.WriteLine(errorOutput);
    }
}
```

